<?php
require_once dirname(__DIR__,3).'/app/AdminBusinessOperations.php';
$operationApplications=AdminBusinessOperations::applications(db());
$operationRows=AdminBusinessOperations::summarize($rows,$operationApplications);
$segmentLabels=['registered'=>'Registrados por personas','imported'=>'Importados del portal','historical'=>'Altas administrativas anteriores','unknown'=>'Origen por revisar'];
$legacySegment=['owner_submitted'=>'registered','public_import'=>'imported','admin_created'=>'historical'];
$segment=(string)($_GET['segment']??$legacySegment[$_GET['origen']??'']??'registered');
if(!isset($segmentLabels[$segment]))$segment='registered';
$filters=['query'=>trim((string)($_GET['q']??'')),'destination'=>(string)($_GET['destino']??''),'category'=>(string)($_GET['categoria']??''),'status'=>(string)($_GET['estado']??''),'segment'=>$segment,'verification'=>(string)($_GET['verificacion']??''),'plan'=>(string)($_GET['plan']??''),'account'=>(string)($_GET['cuenta']??'')];
if($filters['destination']==='0')$filters['destination']='';
$viewRows=array_values(array_filter($operationRows,static fn($row)=>AdminBusinessOperations::matches($row,$filters)));
$operationEntries=$viewRows;
$operationPageCount=max(1,(int)ceil(count($operationEntries)/25));$operationPage=min(max(1,(int)($_GET['pagina']??1)),$operationPageCount);
$operationShown=array_slice($operationEntries,($operationPage-1)*25,25);
$filterFields=['destino'=>['Destino',array_column($options['destinations'],'display_name','id'),'destination'],'categoria'=>['Categoría',array_column($options['categories'],'label','code'),'category'],'estado'=>['Publicación',['draft'=>'Pendiente de publicación','published'=>'Publicado','archived'=>'Retirado'],'status'],'plan'=>['Suscripción',[],'plan'],'cuenta'=>['Cuenta asociada',['yes'=>'Con cuenta asociada','no'=>'Sin cuenta asociada'],'account']];
// Plan options are read from current configuration, not inferred from payment or origin.
$filterFields['plan'][1]=['free'=>'Gratis'];foreach($options['plans'] as $planOption){$code=$planOption['code']??$planOption['plan_code']??null;if($code)$filterFields['plan'][1][$code]=$planOption['name']??$planOption['label']??$code;}
$operationUrl=static fn($page)=>'?'.http_build_query(array_merge(array_intersect_key($_GET,array_flip(['q','destino','categoria','estado','origen','verificacion','plan','cuenta'])),['segment'=>$segment,'tab'=>$tab,'pagina'=>$page]));
?>
