<p><strong>Grupo actual: <?=esc($segmentLabels[$segment])?></strong>. El origen se conserva aunque una ficha importada después tenga una cuenta asociada. Las altas administrativas anteriores se mantienen aparte.</p>
<form method="get" class="business-filter-bar"><label>Grupo de negocios<select name="segment" data-native-select><?php foreach($segmentLabels as $value=>$label):?><option value="<?=esc($value)?>" <?=$segment===$value?'selected':''?>><?=esc($label)?></option><?php endforeach ?></select></label><input type="hidden" name="tab" value="<?=esc($tab)?>"><label>Buscar negocio o destino<input type="search" name="q" value="<?=esc($filters['query'])?>"></label>
<?php foreach($filterFields as $name=>[$label,$values,$key]):?><label><?=esc($label)?><select name="<?=esc($name)?>" data-native-select><option value="">Todos</option><?php foreach($values as $value=>$text):?><option value="<?=esc($value)?>" <?=(string)$value===$filters[$key]?'selected':''?>><?=esc($text)?></option><?php endforeach ?></select></label><?php endforeach ?>
<label>Verificación<select name="verificacion" data-native-select><option value="">Todas</option><?php foreach(['PUBLICO'=>'Fuente pública','VERIFICADO'=>'Verificado','ACTIVO'=>'Activo','PENDIENTE_REVISION'=>'Pendiente de revisión'] as $value=>$text):?><option value="<?=$value?>" <?=$filters['verification']===$value?'selected':''?>><?=$text?></option><?php endforeach ?></select></label>
<button class="pill compact" type="submit">Aplicar filtros</button><a class="pill light compact" href="?tab=<?=esc($tab)?>&amp;segment=<?=esc($segment)?>">Limpiar filtros</a></form>
<p class="notice" role="status"><?=count($viewRows)?> negocios · Página <?=$operationPage?> de <?=$operationPageCount?>. <?=count(array_filter(array_diff_key($filters,['segment'=>true]),static fn($value)=>$value!==''))?> filtros activos.</p>
<div class="destination-admin-table admin-operations-table"><table><thead><tr><th>Negocio</th><th>Destino y categorías</th><th>Publicación</th><th>Cuenta y solicitud</th><th>Plan</th><th>Pendiente y acciones</th></tr></thead><tbody>
<?php foreach($operationShown as $row):?>
<tr><td><strong><?=esc($row['display_name'])?></strong><br><small>Origen registrado: <?=esc(business_origin_label($row['record_origin']))?> · #<?=esc($row['id'])?></small></td><td><?=esc($row['destination_name'])?><br><?=esc(implode(' · ',$row['category_labels']))?></td><td><?=esc(['draft'=>'Pendiente de publicación','published'=>'Publicado','archived'=>'Retirado'][$row['publication_status']]??$row['publication_status'])?><br><small><?=esc(AdminBusinessOperations::informationLabel($row['information_status']))?></small></td><td><?=esc(AdminBusinessOperations::accountLabel($row))?><br><small><?=count($row['applications'])?> solicitudes vinculadas</small><?php foreach($row['applications'] as $application):?><br><a href="solicitud-detalle.php?tipo=account&amp;id=<?=esc($application['id'])?>" target="_blank" rel="noopener">Solicitud #<?=esc($application['id'])?> ↗</a><?php endforeach ?></td><td><?=esc($row['subscription_status']==='sin suscripción'?'Gratis':($filterFields['plan'][1][$row['plan_code']]??$row['plan_code']))?><br><small><?=esc(AdminBusinessOperations::subscriptionLabel($row['subscription_status']))?></small></td><td><?=esc(AdminBusinessOperations::nextStep($row))?><div class="admin-row-actions"><a class="pill light compact" href="negocio-vista-previa.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Ver tarjeta ↗</a><a class="pill light compact" href="negocios.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Editar datos ↗</a><a class="pill light compact" href="suscripciones.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Gestionar plan y publicación ↗</a></div></td></tr>
<?php endforeach ?><?php if(!$operationShown):?><tr><td colspan="6">No hay registros con estos filtros. Puedes limpiar los filtros de este grupo.</td></tr><?php endif ?></tbody></table></div>
